package com.fream.back.domain.m06.service.command;

import com.fream.back.domain.m15.entity.Xzv64;
import com.fream.back.domain.m15.entity.Xkh73Type;
import com.fream.back.domain.m15.service.command.Xkh73CommandService;
import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m16.entity.Xzj27;
import com.fream.back.domain.m06.dto.Xkg34RequestDto;
import com.fream.back.domain.m06.dto.Xqg94RequestDto;
import com.fream.back.domain.m06.dto.Xjt86RequestDto;
import com.fream.back.domain.m06.dto.Xbf54RequestDto;
import com.fream.back.domain.m06.entity.*;
import com.fream.back.domain.m06.exception.*;
import com.fream.back.domain.m06.p05.Xxv33ApiClient;
import com.fream.back.domain.m06.repository.Xbf54Repository;
import com.fream.back.domain.m06.service.query.Xbf54InfoQueryService;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xzz58;
import com.fream.back.domain.m10.entity.Xgg74Status;
import com.fream.back.domain.m10.service.query.Xzz58QueryService;
import com.fream.back.domain.m13.entity.Xrd81;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;





@Service
@RequiredArgsConstructor
@Transactional
@Slf4j
public class Xbf54CommandService {

    private final Xbf54Repository paymentRepository;
    private final Xbf54InfoQueryService paymentInfoQueryService;
    private final Xxv33ApiClient portOneApiClient;
    private final Xkh73CommandService notificationCommandService;
    private final Xzz58QueryService saleBidQueryService;











    public Xbf54 processPayment(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            validatePaymentRequest(order, user, requestDto);

            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());

            Xbf54 payment;

            switch (requestDto.getResolvedPaymentType()) {
                case "CARD":
                    payment = createCardPayment(order, user, (Xqg94RequestDto) requestDto);
                    break;
                case "ACCOUNT":
                    payment = createAccountPayment(order, user, (Xkg34RequestDto) requestDto);
                    break;
                case "GENERAL":
                    payment = createGeneralPayment(order, user, (Xjt86RequestDto) requestDto);
                    break;
                default:
                    throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
            }


            notifyUsersAndUpdateSaleStatus(order, payment);

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), payment.getId(), payment.getStatus());

            return payment;
        } catch (Xbf54Exception e) {
            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getMessage(), e);
            throw new Xdf64Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 처리 총 소요 시간: {}ms", duration.toMillis());
        }
    }









    private void validatePaymentRequest(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
        if (order == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
        }

        if (user == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
        }

        if (requestDto == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
        }


        if (!order.getId().equals(requestDto.getOrderId())) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
        }

        if (!user.getEmail().equals(requestDto.getUserEmail())) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
        }


        if (requestDto.getPaidAmount() <= 0) {
            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_AMOUNT,
                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
        }
    }










    private Xbf54 createCardPayment(Xdg64 order, Xrd81 user, Xqg94RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
                    order.getId(), requestDto.getPaymentInfoId());


            Xbf54Info paymentInfo;
            try {
                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
                if (paymentInfo == null) {
                    throw new Xjs44Exception("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
                }
            } catch (Xbf54Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xjs44Exception("결제 정보 조회 중 오류가 발생했습니다.", e);
            }


            Map<String, Object> response;
            try {
                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
            } catch (Xbf54Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xbf54ApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
            }


            Xqg94 cardPayment = Xqg94.builder()
                    .cardNumber(paymentInfo.getCardNumber())
                    .cardPassword(paymentInfo.getCardPassword())
                    .cardExpiration(paymentInfo.getExpirationDate())
                    .birthDate(paymentInfo.getBirthDate())
                    .cardType((String) response.get("card_name"))
                    .paidAmount(requestDto.getPaidAmount())
                    .impUid((String) response.get("imp_uid"))
                    .receiptUrl((String) response.get("receipt_url"))
                    .pgProvider((String) response.get("pg_provider"))
                    .pgTid((String) response.get("pg_tid"))
                    .build();

            cardPayment.assignOrder(order);
            cardPayment.assignUser(user);

            if ("success".equals(response.get("status"))) {
                cardPayment.updateStatus(Xbf54Status.PAID);
                cardPayment.updateSuccessStatus(true);
            }

            Xqg94 savedPayment = (Xqg94) paymentRepository.save(cardPayment);
            log.info("카드 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("카드 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xbf54Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("카드 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xdf64Exception("카드 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }










    private Xbf54 createAccountPayment(Xdg64 order, Xrd81 user, Xkg34RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("계좌이체 결제 처리 시작: 주문ID={}, 은행={}",
                    order.getId(), requestDto.getBankName());


            try {
                validateBank(requestDto.getBankName());
            } catch (Exception e) {
                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_BANK_INFO,
                        "유효하지 않은 은행 정보: " + requestDto.getBankName());
            }

            Xkg34 accountPayment = Xkg34.builder()
                    .bankName(requestDto.getBankName())
                    .accountNumber(requestDto.getAccountNumber())
                    .accountHolder(requestDto.getAccountHolder())
                    .receiptRequested(requestDto.isReceiptRequested())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            accountPayment.assignOrder(order);
            accountPayment.assignUser(user);
            accountPayment.updateStatus(Xbf54Status.PENDING);

            Xkg34 savedPayment = (Xkg34) paymentRepository.save(accountPayment);
            log.info("계좌이체 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("계좌이체 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xbf54Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("계좌이체 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xdf64Exception("계좌이체 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }










    private Xbf54 createGeneralPayment(Xdg64 order, Xrd81 user, Xjt86RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("일반 결제 처리 시작: 주문ID={}, impUid={}",
                    order.getId(), requestDto.getImpUid());


            if (requestDto.getImpUid() == null || requestDto.getImpUid().isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                        "결제 ID(impUid)는 필수 항목입니다.");
            }

            Xjt86 generalPayment = Xjt86.builder()
                    .impUid(requestDto.getImpUid())
                    .pgProvider(requestDto.getPgProvider())
                    .receiptUrl(requestDto.getReceiptUrl())
                    .buyerName(requestDto.getBuyerName())
                    .buyerEmail(requestDto.getBuyerEmail())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            generalPayment.assignOrder(order);
            generalPayment.assignUser(user);
            generalPayment.updateSuccessStatus(true);
            generalPayment.updateStatus(Xbf54Status.PAID);

            Xjt86 savedPayment = (Xjt86) paymentRepository.save(generalPayment);
            log.info("일반 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("일반 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xbf54Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("일반 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xdf64Exception("일반 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private void handleRefundIfNecessary(Xbf54 payment) {
        Instant start = Instant.now();
        try {
            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
                return;
            }

            log.info("결제 환불 처리 시작: 결제ID={}, impUid={}", payment.getId(), payment.getImpUid());

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(Xbf54Status.REFUNDED);
                paymentRepository.save(payment);
                log.info("결제 환불 처리 완료: 결제ID={}, 상태=REFUNDED", payment.getId());
            } else {
                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
            }


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
        } catch (Xbf54Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private void notifyUsersAndUpdateSaleStatus(Xdg64 order, Xbf54 payment) {
        try {
            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());


            Xzj27 orderBid = order.getOrderBid();
            if (orderBid == null) {

                Xzz58 saleBid = saleBidQueryService.findByOrderId(order.getId());
                if (saleBid == null) {
                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
                    return;
                }

                Xgg74 sale = saleBid.getSale();
                if (sale == null) {
                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
                    return;
                }

                sendNotifications(order, sale);
                sale.updateStatus(Xgg74Status.SOLD);
                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
                return;
            }


            Xgg74 sale = orderBid.getSale();
            if (sale == null) {
                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
                return;
            }

            sendNotifications(order, sale);


            sale.updateStatus(Xgg74Status.SOLD);
            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
        } catch (Exception e) {

            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
        }
    }







    private void sendNotifications(Xdg64 order, Xgg74 sale) {
        try {
            Xrd81 buyer = order.getUser();
            if (buyer != null) {
                notificationCommandService.createNotification(
                        buyer.getId(),
                        Xzv64.SHOPPING,
                        Xkh73Type.BID,
                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
                );
                log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
            }

            Xrd81 seller = sale.getSeller();
            if (seller != null) {
                notificationCommandService.createNotification(
                        seller.getId(),
                        Xzv64.SHOPPING,
                        Xkh73Type.BID,
                        "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
                );
                log.debug("판매자 알림 전송 완료: 판매자ID={}", seller.getId());
            }
        } catch (Exception e) {

            log.warn("결제 완료 알림 전송 중 오류 발생: 주문ID={}, 판매ID={}, 오류={}",
                    order.getId(), sale.getId(), e.getMessage());
        }
    }







    private void validateBank(String bankName) {
        try {
            if (bankName == null || bankName.isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_BANK_INFO, "은행 이름은 필수입니다.");
            }

            try {
                Xpt57.valueOf(bankName.toUpperCase());
            } catch (IllegalArgumentException e) {
                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_BANK_INFO,
                        "지원하지 않는 은행입니다: " + bankName);
            }
        } catch (Xbf54Exception e) {
            throw e;
        } catch (Exception e) {
            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_BANK_INFO,
                    "은행 정보 검증 중 오류가 발생했습니다.", e);
        }
    }








    @Transactional
    public void updatePaymentStatus(Xbf54 payment, Xbf54Status newStatus) {
        Instant start = Instant.now();
        try {
            if (payment == null) {
                throw new Xvt76Exception("결제 정보가 없습니다.");
            }

            if (!payment.getStatus().canTransitionTo(newStatus)) {
                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
            }

            log.info("결제 상태 변경: 결제ID={}, 현재상태={}, 새상태={}",
                    payment.getId(), payment.getStatus(), newStatus);

            payment.updateStatus(newStatus);
            paymentRepository.save(payment);

            log.info("결제 상태 변경 완료: 결제ID={}, 상태={}", payment.getId(), newStatus);


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 상태 변경 처리 시간: {}ms", duration.toMillis());
        } catch (Xbf54Exception e) {
            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    payment != null ? payment.getId() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment != null ? payment.getId() : "null", e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_UPDATE_FAILED,
                    "결제 상태 변경 중 오류가 발생했습니다.", e);
        }
    }








    @Transactional
    public String refundPayment(Long paymentId) {
        Instant start = Instant.now();
        try {
            log.info("결제 환불 요청 시작: 결제ID={}", paymentId);


            Xbf54 payment = paymentRepository.findById(paymentId)
                    .orElseThrow(() -> new Xvt76Exception("결제 ID: " + paymentId + "를 찾을 수 없습니다."));


            if (!payment.getStatus().canTransitionTo(Xbf54Status.REFUND_REQUESTED)) {
                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
            }


            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 가능한 결제 ID가 없습니다.");
            }

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(Xbf54Status.REFUNDED);
                paymentRepository.save(payment);
                log.info("결제 환불 요청 성공: 결제ID={}, 상태=REFUNDED", paymentId);


                sendRefundNotification(payment);


                Instant end = Instant.now();
                Duration duration = Duration.between(start, end);
                log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());

                return "환불이 성공적으로 완료되었습니다.";
            } else {
                payment.updateStatus(Xbf54Status.REFUND_REQUESTED);
                paymentRepository.save(payment);
                log.warn("결제 환불 요청 실패: 결제ID={}, 상태=REFUND_REQUESTED", paymentId);
                return "환불 요청이 실패하였습니다. 관리자에게 문의하세요.";
            }
        } catch (Xbf54Exception e) {
            log.error("결제 환불 요청 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    paymentId, e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 환불 요청 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    paymentId, e.getMessage(), e);
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 요청 중 오류가 발생했습니다: " + e.getMessage());
        }
    }






    private void sendRefundNotification(Xbf54 payment) {
        try {
            Xrd81 user = payment.getUser();
            if (user == null) {
